    timestamp: r.timestamp,
    temperature: r.temperature,
    windSpeed: r.windSpeed,
    windDirection: r.windDirection,
    visibility: r.visibility,
    cloudCover: r.cloudCover,
    pressure: r.pressure,
    weatherCode: r.weatherCode,
  }));

